struct timespec req = {
    .tv_sec = 1,              // 1 second
    .tv_nsec = 500000000      // 500 milliseconds
};
struct timespec rem;

// Loop to handle interruptions (EINTR) and restart the sleep
while (nanosleep(&req, &rem) == -1) {
    if (errno == EINTR) {
        req = rem; // Use remaining time for the next attempt
        continue;
    }
    // Handle EFAULT or EINVAL errors
    perror("nanosleep failed");
    break;
}

// Check rem if interested in exact time remaining upon exit
if (rem.tv_sec > 0 || rem.tv_nsec > 0) {
    // Interruption occurred
}
